def max_pieces(n, a, b):
    total_pieces = a + b
    if total_pieces < n:
        return -1
    min_pieces = total_pieces // n
    if (a >= n or b >= n) and min_pieces == 1:
        return 1
    if a > b:
        if a % n == 0:
            return a // n
        else:
            return a // n + 1
    else:
        if b % n == 0:
            return b // n
        else:
            return b // n + 1

